import type { RenderContext, RendererModule } from "./types";

/**
 * `<x-icon name="arrow-right" tone="ok" label="Passed">` renders an inline
 * Heroicons 20/solid svg. The icon data lives in its own chunk (`virtual:heroicons`,
 * generated by vite.config.ts from the installed heroicons package) and is only
 * fetched when a document actually uses `<x-icon>`.
 *
 * SVG comes from the build, not the network: the report CSP allows `connect-src`
 * to `assets/` only. Size, baseline alignment and tones are pure CSS (report.css),
 * so the box is reserved before the svg lands — no layout shift. `tone` needs no
 * JavaScript at all: it is an authored attribute the stylesheet matches on.
 */

let icons: Record<string, string> | null = null;
const unknown = new Set<string>();

async function iconData(): Promise<Record<string, string>> {
	if (!icons) icons = (await import("virtual:heroicons")).default;
	return icons;
}

function sync(el: HTMLElement, data: Record<string, string>): void {
	const name = el.getAttribute("name")?.trim() ?? "";
	const label = el.getAttribute("label")?.trim() ?? "";

	if (label) {
		el.setAttribute("role", "img");
		el.setAttribute("aria-label", label);
		el.removeAttribute("aria-hidden");
	} else {
		el.removeAttribute("role");
		el.removeAttribute("aria-label");
		el.setAttribute("aria-hidden", "true");
	}

	if (el.dataset.icon === name) return;
	const svg = name === "" ? undefined : data[name];
	if (!svg) {
		el.replaceChildren();
		delete el.dataset.icon;
		if (name && !unknown.has(name)) {
			unknown.add(name);
			console.warn(`[artifacts] unknown icon "${name}" — use a Heroicons 20/solid name (heroicons.com)`);
		}
		return;
	}
	// Trusted by construction: build-time markup from the heroicons package.
	el.innerHTML = svg;
	el.dataset.icon = name;
}

export async function render(root: ParentNode, _ctx: RenderContext): Promise<void> {
	const elements = [...root.querySelectorAll<HTMLElement>("x-icon")];
	if (!elements.length) return;
	const data = await iconData();
	for (const el of elements) sync(el, data);
}

export function reset(root: ParentNode): void {
	for (const el of root.querySelectorAll<HTMLElement>("x-icon")) {
		if (!el.dataset.icon && !el.firstElementChild) continue;
		el.replaceChildren();
		delete el.dataset.icon;
		el.removeAttribute("role");
		el.removeAttribute("aria-label");
		el.removeAttribute("aria-hidden");
	}
}

const module_: RendererModule = { render, reset };
export default module_;
